 69	    @Nullable
 70	    public static ReportActivityNotificationIntents getReportActivityNotificationIntents(@NonNull Context context,
 71	                                                                                         @NonNull ReportInfo reportInfo) {
 72	        ReportActivity.NewInstanceResult result = ReportActivity.newInstance(context, reportInfo);
 73	        if (result.contentIntent == null) return null;
 74	
 75	        int notificationId = getNextNotificationId(context);
 76	        PendingIntent contentIntent = PendingIntent.getActivity(context, notificationId, result.contentIntent,
 77	            PendingIntent.FLAG_UPDATE_CURRENT);
 78	
 79	        PendingIntent deleteIntent = null;
 80	        if (result.deleteIntent != null) {
 81	            deleteIntent = PendingIntent.getBroadcast(context, notificationId, result.deleteIntent,
 82	                PendingIntent.FLAG_UPDATE_CURRENT);
 83	        }
 84	
 85	        return new ReportActivityNotificationIntents(notificationId, contentIntent, deleteIntent);
 86	    }
