 89	                                              @NonNull Context termuxPackageContext,
 90	                                              @NonNull String channelId,
 91	                                              @NonNull String channelName,
 92	                                              @NonNull CharSequence title,
 93	                                              @NonNull String notificationTextString,
 94	                                              @NonNull ReportActivityNotificationIntents reportActivityNotificationIntents) {
 95	        setupHighPriorityNotificationChannel(termuxPackageContext, channelId, channelName);
 96	
 97	        CharSequence notificationTextCharSequence =
 98	            MarkdownUtils.getSpannedMarkdownText(termuxPackageContext, notificationTextString);
 99	
100	        Notification.Builder builder = getTermuxOrPluginAppNotificationBuilder(
101	            currentPackageContext, termuxPackageContext, channelId, Notification.PRIORITY_HIGH,
102	            title, notificationTextCharSequence, notificationTextCharSequence,
103	            reportActivityNotificationIntents.contentIntent, reportActivityNotificationIntents.deleteIntent,
104	            NotificationUtils.NOTIFICATION_MODE_VIBRATE);
105	        if (builder == null) return;
106	
107	        NotificationManager notificationManager = NotificationUtils.getNotificationManager(termuxPackageContext);
108	        if (notificationManager != null) {
109	            notificationManager.notify(reportActivityNotificationIntents.notificationId, builder.build());
110	        }
111	    }
